lxb_css_parser_failed_set_by_id(lxb_css_parser_t *parser, int idx, bool is)
{
    lxb_css_syntax_rule_t *rules = parser->rules + idx;

    if (rules > parser->rules_begin && rules < parser->rules_end) {
        rules->failed = is;
    }
}

