#define LXB_SELECTORS_VERSION_STRING LEXBOR_STRINGIZE(LXB_SELECTORS_VERSION_MAJOR) "."   \
                                     LEXBOR_STRINGIZE(LXB_SELECTORS_VERSION_MINOR) "."   \
